fn solve(word: Vec<char>) -> Vec<char> {
    // Helper to check membership in Set A
    fn is_set_a(c: char) -> bool {
        matches!(
            c,
            'A' | 'E' | 'F' | 'H' | 'I' | 'K' | 'L' | 'M' | 'N' | 'T' | 'V' | 'W' | 'X' | 'Y' | 'Z'
        )
    }

    // Track whether all letters seen so far are in A or all in B
    let (mut all_a, mut all_b) = (true, true);

    for c in word {
        if is_set_a(c) {
            all_b = false;
        } else {
            all_a = false;
        }
    }

    if all_a || all_b {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

